  /// @param size          Size of the packet.
  /// @param src_addr      Source address where this packet was received
  /// from.
  /// @param src_addr_len  The length of source address.
  external ffi.Pointer<
    ffi.NativeFunction<
      ffi.Void Function(
        ffi.Pointer<pj_ice_sess> ice,
        ffi.UnsignedInt comp_id,
        ffi.UnsignedInt transport_id,
        ffi.Pointer<ffi.Void> pkt,
        pj_size_t size,
        ffi.Pointer<pj_sockaddr_t> src_addr,
        ffi.UnsignedInt src_addr_len,
      )
    >
  >
  on_rx_data;

  static ffi.Pointer<pj_ice_sess_cb> $allocate(
    ffi.Allocator $allocator, {
    required ffi.Pointer<
      ffi.NativeFunction<ffi.Void Function(ffi.Pointer<pj_ice_sess> ice)>
    >
    on_valid_pair,
    required ffi.Pointer<
      ffi.NativeFunction<
        ffi.Void Function(ffi.Pointer<pj_ice_sess> ice, pj_status_t status)
      >
    >
    on_ice_complete,
    required ffi.Pointer<
      ffi.NativeFunction<
        pj_status_t Function(
          ffi.Pointer<pj_ice_sess> ice,
          ffi.UnsignedInt comp_id,
          ffi.UnsignedInt transport_id,
          ffi.Pointer<ffi.Void> pkt,
          pj_size_t size,
          ffi.Pointer<pj_sockaddr_t> dst_addr,
          ffi.UnsignedInt dst_addr_len,
        )
      >
    >
    on_tx_pkt,
    required ffi.Pointer<
      ffi.NativeFunction<
        ffi.Void Function(
          ffi.Pointer<pj_ice_sess> ice,
          ffi.UnsignedInt comp_id,
          ffi.UnsignedInt transport_id,
          ffi.Pointer<ffi.Void> pkt,
          pj_size_t size,
          ffi.Pointer<pj_sockaddr_t> src_addr,
          ffi.UnsignedInt src_addr_len,
        )
      >
    >
    on_rx_data,
  }) => $allocator<pj_ice_sess_cb>()
    ..ref.on_valid_pair = on_valid_pair
    ..ref.on_ice_complete = on_ice_complete
    ..ref.on_tx_pkt = on_tx_pkt
    ..ref.on_rx_data = on_rx_data;
}

/// This structure describes an ICE connectivity check. An ICE check
/// contains a candidate pair, and will involve sending STUN Binding
/// Request transaction for the purposes of verifying connectivity.
/// A check is sent from the local candidate to the remote candidate
/// of a candidate pair.
final class pj_ice_sess_check extends ffi.Struct {
  /// Pointer to local candidate entry of this check.
  external ffi.Pointer<pj_ice_sess_cand> lcand;

  /// Pointer to remote candidate entry of this check.
  external ffi.Pointer<pj_ice_sess_cand> rcand;

  /// Foundation index, referring to foundation array defined in checklist.
  @ffi.Int()
  external int foundation_idx;

  /// Check priority.
  external pj_timestamp prio;

  /// Connectivity check state.
  @ffi.UnsignedInt()
  external int stateAsInt;

  pj_ice_sess_check_state get state =>
      pj_ice_sess_check_state.fromValue(stateAsInt);
  set state(pj_ice_sess_check_state value) => stateAsInt = value.value;

  /// STUN transmit data containing STUN Binding request that was sent
  /// as part of this check. The value will only be set when this check
  /// has a pending transaction, and is used to cancel the transaction
  /// when other check has succeeded.
  external ffi.Pointer<pj_stun_tx_data> tdata;

  /// Flag to indicate whether this check is nominated. A nominated check
  /// contains USE-CANDIDATE attribute in its STUN Binding request.
  @pj_bool_t()
  external int nominated;

  /// When the check failed, this will contain the failure status of the
  /// STUN transaction.
  @pj_status_t()
  external int err_code;
}

/// This enumeration describes the state of ICE check.
enum pj_ice_sess_check_state {
  /// A check for this pair hasn't been performed, and it can't
  /// yet be performed until some other check succeeds, allowing this
  /// pair to unfreeze and move into the Waiting state.
  PJ_ICE_SESS_CHECK_STATE_FROZEN(0),

  /// A check has not been performed for this pair, and can be
  /// performed as soon as it is the highest priority Waiting pair on
  /// the check list.
  PJ_ICE_SESS_CHECK_STATE_WAITING(1),

  /// A check has not been performed for this pair, and can be
  /// performed as soon as it is the highest priority Waiting pair on
  /// the check list.
  PJ_ICE_SESS_CHECK_STATE_IN_PROGRESS(2),

  /// A check has not been performed for this pair, and can be
  /// performed as soon as it is the highest priority Waiting pair on
  /// the check list.
  PJ_ICE_SESS_CHECK_STATE_SUCCEEDED(3),

  /// A check for this pair was already done and failed, either
  /// never producing any response or producing an unrecoverable failure
  /// response.
  PJ_ICE_SESS_CHECK_STATE_FAILED(4);

  final int value;
  const pj_ice_sess_check_state(this.value);

  static pj_ice_sess_check_state fromValue(int value) => switch (value) {
    0 => PJ_ICE_SESS_CHECK_STATE_FROZEN,
    1 => PJ_ICE_SESS_CHECK_STATE_WAITING,
    2 => PJ_ICE_SESS_CHECK_STATE_IN_PROGRESS,
    3 => PJ_ICE_SESS_CHECK_STATE_SUCCEEDED,
    4 => PJ_ICE_SESS_CHECK_STATE_FAILED,
    _ => throw ArgumentError(
      'Unknown value for pj_ice_sess_check_state: $value',
    ),
  };
}

/// This structure represents ICE check list, that is an ordered set of
/// candidate pairs that an agent will use to generate checks.
final class pj_ice_sess_checklist extends ffi.Struct {
  /// The checklist state.
  @ffi.UnsignedInt()
  external int stateAsInt;

  pj_ice_sess_checklist_state get state =>
      pj_ice_sess_checklist_state.fromValue(stateAsInt);
  set state(pj_ice_sess_checklist_state value) => stateAsInt = value.value;

  /// Number of candidate pairs (checks).
  @ffi.UnsignedInt()
  external int count;

  /// Array of candidate pairs (checks).
  @ffi.Array.multi([32])
  external ffi.Array<pj_ice_sess_check> checks;

  /// Number of foundations.
  @ffi.UnsignedInt()
  external int foundation_cnt;

  /// Array of foundations, check foundation index refers to this array.
  @ffi.Array.multi([64])
  external ffi.Array<pj_str_t> foundation;

  /// A timer used to perform periodic check for this checklist.
  external pj_timer_entry timer;
}

/// This enumeration describes ICE checklist state.
enum pj_ice_sess_checklist_state {
  /// The checklist is not yet running.
  PJ_ICE_SESS_CHECKLIST_ST_IDLE(0),

  /// In this state, ICE checks are still in progress for this
  /// media stream.
  PJ_ICE_SESS_CHECKLIST_ST_RUNNING(1),

  /// In this state, ICE checks have completed for this media stream,
  /// either successfully or with failure.
  PJ_ICE_SESS_CHECKLIST_ST_COMPLETED(2);

  final int value;
  const pj_ice_sess_checklist_state(this.value);

  static pj_ice_sess_checklist_state fromValue(int value) => switch (value) {
    0 => PJ_ICE_SESS_CHECKLIST_ST_IDLE,
    1 => PJ_ICE_SESS_CHECKLIST_ST_RUNNING,
    2 => PJ_ICE_SESS_CHECKLIST_ST_COMPLETED,
    _ => throw ArgumentError(
      'Unknown value for pj_ice_sess_checklist_state: $value',
    ),
  };
}

/// This structure describes ICE component.
/// A media stream may require multiple components, each of which has
/// to work for the media stream as a whole to work.  For media streams
/// based on RTP, there are two components per media stream - one for RTP,
/// and one for RTCP.
final class pj_ice_sess_comp extends ffi.Struct {
  /// Pointer to ICE check with highest priority which connectivity check
  /// has been successful. The value will be NULL if a no successful check
  /// has not been found for this component.
  external ffi.Pointer<pj_ice_sess_check> valid_check;

  /// Pointer to ICE check with highest priority which connectivity check
  /// has been successful and it has been nominated. The value may be NULL
  /// if there is no such check yet.
  external ffi.Pointer<pj_ice_sess_check> nominated_check;

  /// The STUN session to be used to send and receive STUN messages for this
  /// component.
  external ffi.Pointer<pj_stun_session> stun_sess;

  /// The remote candidate checked address. This is expected address that
  /// the remote going to use.
  external pj_sockaddr rcand_check_addr;
}

/// This structure describes various ICE session options. Application
/// configure the ICE session with these options by calling
/// #pj_ice_sess_set_options().
final class pj_ice_sess_options extends ffi.Struct {
  /// Specify whether to use aggressive nomination. This setting can only
  /// be enabled when trickle ICE is disabled.
  @pj_bool_t()
  external int aggressive;

  /// For controlling agent if it uses regular nomination, specify the delay
  /// to perform nominated check (connectivity check with USE-CANDIDATE
  /// attribute) after all components have a valid pair.
  ///
  /// Default value is PJ_ICE_NOMINATED_CHECK_DELAY.
  @ffi.UnsignedInt()
  external int nominated_check_delay;

  /// For a controlled agent, specify how long it wants to wait (in
  /// milliseconds) for the controlling agent to complete sending
  /// connectivity check with nominated flag set to true for all components
  /// after the controlled agent has found that all connectivity checks in
  /// its checklist have been completed and there is at least one successful
  /// (but not nominated) check for every component.
  ///
  /// Default value for this option is
  /// ICE_CONTROLLED_AGENT_WAIT_NOMINATION_TIMEOUT. Specify -1 to disable
  /// this timer.
  @ffi.Int()
  external int controlled_agent_want_nom_timeout;

  /// Trickle ICE mode. Note that, when enabled, aggressive nomination will
  /// be automatically disabled.
  ///
  /// Default value is PJ_ICE_SESS_TRICKLE_DISABLED.
  @ffi.UnsignedInt()
  external int trickleAsInt;

  pj_ice_sess_trickle get trickle =>
      pj_ice_sess_trickle.fromValue(trickleAsInt);
  set trickle(pj_ice_sess_trickle value) => trickleAsInt = value.value;

  /// Specify whether to check the source address of the incoming messages.
  /// The source address will be compared to the remote candidate which has
  /// a completed connectivity check or received a connectivity check.
  ///
  /// Default value is PJ_ICE_SESS_CHECK_SRC_ADDR.
  @pj_bool_t()
  external int check_src_addr;

  static ffi.Pointer<pj_ice_sess_options> $allocate(
    ffi.Allocator $allocator, {
    required int aggressive,
    required int nominated_check_delay,
    required int controlled_agent_want_nom_timeout,
    required pj_ice_sess_trickle trickle,
    required int check_src_addr,
  }) => $allocator<pj_ice_sess_options>()
    ..ref.aggressive = aggressive
    ..ref.nominated_check_delay = nominated_check_delay
    ..ref.controlled_agent_want_nom_timeout = controlled_agent_want_nom_timeout
    ..ref.trickle = trickle
    ..ref.check_src_addr = check_src_addr;
}

/// This enumeration describes the role of the ICE agent.
enum pj_ice_sess_role {
  /// The role is unknown.
  PJ_ICE_SESS_ROLE_UNKNOWN(0),

  /// The ICE agent is in controlled role.
  PJ_ICE_SESS_ROLE_CONTROLLED(1),

  /// The ICE agent is in controlling role.
  PJ_ICE_SESS_ROLE_CONTROLLING(2);

  final int value;
  const pj_ice_sess_role(this.value);

  static pj_ice_sess_role fromValue(int value) => switch (value) {
    0 => PJ_ICE_SESS_ROLE_UNKNOWN,
    1 => PJ_ICE_SESS_ROLE_CONTROLLED,
    2 => PJ_ICE_SESS_ROLE_CONTROLLING,
    _ => throw ArgumentError('Unknown value for pj_ice_sess_role: $value'),
  };
}

/// This enumeration describes the modes of trickle ICE.
enum pj_ice_sess_trickle {
  /// Trickle ICE is disabled.
  PJ_ICE_SESS_TRICKLE_DISABLED(0),

  /// Half trickle ICE. This mode has better interoperability when remote
  /// capability of ICE trickle is unknown at ICE initialization.
  ///
  /// As ICE initiator, it will convey all local ICE candidates to remote
  /// (just like regular ICE) and be ready to receive either response,
  /// trickle or regular ICE. As ICE answerer, it will do trickle ICE if
  /// it receives an offer with trickle ICE indication, otherwise it will do
  /// regular ICE.
  PJ_ICE_SESS_TRICKLE_HALF(1),

  /// Full trickle ICE. Only use this mode if it is known that that remote
  /// supports trickle ICE. The discovery whether remote supports trickle
  /// ICE should be done prior to ICE initialization and done by application
  /// (ICE does not provide the discovery mechanism).
  PJ_ICE_SESS_TRICKLE_FULL(2);

  final int value;
  const pj_ice_sess_trickle(this.value);

  static pj_ice_sess_trickle fromValue(int value) => switch (value) {
    0 => PJ_ICE_SESS_TRICKLE_DISABLED,
    1 => PJ_ICE_SESS_TRICKLE_HALF,
    2 => PJ_ICE_SESS_TRICKLE_FULL,
    _ => throw ArgumentError('Unknown value for pj_ice_sess_trickle: $value'),
  };
}

final class pj_ice_strans extends ffi.Opaque {}

/// This structure contains callbacks that will be called by the
/// ICE stream transport.
final class pj_ice_strans_cb extends ffi.Struct {
  /// This callback will be called when the ICE transport receives
  /// incoming packet from the sockets which is not related to ICE
  /// (for example, normal RTP/RTCP packet destined for application).
  ///
  /// @param ice_st        The ICE stream transport.
  /// @param comp_id       The component ID.
  /// @param pkt           The packet.
  /// @param size          Size of the packet.
  /// @param src_addr      Source address of the packet.
  /// @param src_addr_len  Length of the source address.
  external ffi.Pointer<
    ffi.NativeFunction<
      ffi.Void Function(
        ffi.Pointer<pj_ice_strans> ice_st,
        ffi.UnsignedInt comp_id,
        ffi.Pointer<ffi.Void> pkt,
        pj_size_t size,
        ffi.Pointer<pj_sockaddr_t> src_addr,
        ffi.UnsignedInt src_addr_len,
      )
    >
  >
  on_rx_data;

  /// This callback is optional and will be called to notify the status of
  /// async send operations.
  ///
  /// @param ice_st        The ICE stream transport.
  /// @param sent          If value is positive non-zero it indicates the
  /// number of data sent. When the value is negative,
  /// it contains the error code which can be retrieved
  /// by negating the value (i.e. status=-sent).
  external ffi.Pointer<
    ffi.NativeFunction<
      ffi.Void Function(ffi.Pointer<pj_ice_strans> sock, pj_ssize_t sent)
    >
  >
  on_data_sent;

  /// An optional callback that will be called by the ICE transport when a
  /// valid pair has been found during ICE negotiation.
  ///
  /// @param ice_st        The ICE stream transport.
  external ffi.Pointer<
    ffi.NativeFunction<ffi.Void Function(ffi.Pointer<pj_ice_strans> ice_st)>
  >
  on_valid_pair;

  /// Callback to report status of various ICE operations.
  ///
  /// @param ice_st        The ICE stream transport.
  /// @param op            The operation which status is being reported.
  /// @param status        Operation status.
  external ffi.Pointer<
    ffi.NativeFunction<
      ffi.Void Function(
        ffi.Pointer<pj_ice_strans> ice_st,
        ffi.UnsignedInt op,
        pj_status_t status,
      )
    >
  >
  on_ice_complete;

  /// Callback to report a new ICE local candidate, e.g: after successful
  /// STUN Binding, after a successful TURN allocation. Only new candidates
  /// whose type is server reflexive or relayed will be notified via this
  /// callback. This callback also indicates end-of-candidate via parameter
  /// 'last'.
  ///
  /// Trickle ICE can use this callback to convey the new candidate
  /// to remote agent and monitor end-of-candidate indication.
  ///
  /// @param ice_st        The ICE stream transport.
  /// @param cand          The new local candidate, can be NULL when the last
  /// local candidate initialization failed/timeout.
  /// @param end_of_cand   PJ_TRUE if this is the last of local candidate.
  external ffi.Pointer<
    ffi.NativeFunction<
      ffi.Void Function(
        ffi.Pointer<pj_ice_strans> ice_st,
        ffi.Pointer<pj_ice_sess_cand> cand,
        pj_bool_t end_of_cand,
      )
    >
  >
  on_new_candidate;

  static ffi.Pointer<pj_ice_strans_cb> $allocate(
    ffi.Allocator $allocator, {
    required ffi.Pointer<
      ffi.NativeFunction<
        ffi.Void Function(
          ffi.Pointer<pj_ice_strans> ice_st,
          ffi.UnsignedInt comp_id,
          ffi.Pointer<ffi.Void> pkt,
          pj_size_t size,
          ffi.Pointer<pj_sockaddr_t> src_addr,
          ffi.UnsignedInt src_addr_len,
        )
      >
    >
    on_rx_data,
    required ffi.Pointer<
      ffi.NativeFunction<
        ffi.Void Function(ffi.Pointer<pj_ice_strans> sock, pj_ssize_t sent)
      >
    >
    on_data_sent,
    required ffi.Pointer<
      ffi.NativeFunction<ffi.Void Function(ffi.Pointer<pj_ice_strans> ice_st)>
    >
    on_valid_pair,
    required ffi.Pointer<
      ffi.NativeFunction<
        ffi.Void Function(
          ffi.Pointer<pj_ice_strans> ice_st,
          ffi.UnsignedInt op,
          pj_status_t status,
        )
      >
    >
    on_ice_complete,
    required ffi.Pointer<
      ffi.NativeFunction<
        ffi.Void Function(
          ffi.Pointer<pj_ice_strans> ice_st,
          ffi.Pointer<pj_ice_sess_cand> cand,
          pj_bool_t end_of_cand,
        )
      >
    >
    on_new_candidate,
  }) => $allocator<pj_ice_strans_cb>()
    ..ref.on_rx_data = on_rx_data
    ..ref.on_data_sent = on_data_sent
    ..ref.on_valid_pair = on_valid_pair
    ..ref.on_ice_complete = on_ice_complete
    ..ref.on_new_candidate = on_new_candidate;
}

/// This structure describes ICE stream transport configuration. Application
/// should initialize the structure by calling #pj_ice_strans_cfg_default()
/// before changing the settings.
final class pj_ice_strans_cfg extends ffi.Struct {
  /// The address family which will be used as the default address
  /// in the SDP offer. Setting this to pj_AF_UNSPEC() means that
  /// the address family will not be considered during the process
  /// of default candidate selection.
  ///
  /// The default value is pj_AF_INET() (IPv4).
  @ffi.Int()
  external int af;

  /// STUN configuration which contains the timer heap and
  /// ioqueue instance to be used, and STUN retransmission
  /// settings. This setting is mandatory.
  ///
  /// The default value is all zero. Application must initialize
  /// this setting with #pj_stun_config_init().
  external pj_stun_config stun_cfg;

  /// DNS resolver to be used to resolve servers. If DNS SRV
  /// resolution is required, the resolver must be set.
  ///
  /// The default value is NULL.
  external ffi.Pointer<pj_dns_resolver> resolver;

  /// This contains various STUN session options. Once the ICE stream
  /// transport is created, application may also change the options
  /// with #pj_ice_strans_set_options().
  external pj_ice_sess_options opt;

  /// Warning: this field is deprecated, please use \a stun_tp field instead.
  /// To maintain backward compatibility, if \a stun_tp_cnt is zero, the
  /// value of this field will be copied to \a stun_tp.
  ///
  /// STUN and local transport settings. This specifies the settings
  /// for local UDP socket address and STUN resolved address.
  external pj_ice_strans_stun_cfg stun;

  /// Number of STUN transports.
  ///
  /// Default: 0
  @ffi.UnsignedInt()
  external int stun_tp_cnt;

  /// STUN and local transport settings. This specifies the settings
  /// for local UDP socket address and STUN resolved address.
  @ffi.Array.multi([2])
  external ffi.Array<pj_ice_strans_stun_cfg> stun_tp;

  /// Warning: this field is deprecated, please use \a turn_tp field instead.
  /// To maintain backward compatibility, if \a turn_tp_cnt is zero, the
  /// value of this field will be copied to \a turn_tp.
  ///
  /// TURN transport settings.
  external pj_ice_strans_turn_cfg turn;

  /// Number of TURN transports.
  ///
  /// Default: 0
  @ffi.UnsignedInt()
  external int turn_tp_cnt;

  /// TURN transport settings.
  @ffi.Array.multi([3])
  external ffi.Array<pj_ice_strans_turn_cfg> turn_tp;

  /// Number of send buffers used for pj_ice_strans_sendto2(). If the send
  /// buffers are full, pj_ice_strans_sendto()/sendto2() will return
  /// PJ_EBUSY.
  ///
  /// Set this to 0 to disable buffering (then application will have to
  /// maintain the buffer passed to pj_ice_strans_sendto()/sendto2()
  /// until it has been sent).
  ///
  /// Default: 4
  @ffi.UnsignedInt()
  external int num_send_buf;

  /// Buffer size used for pj_ice_strans_sendto2().
  ///
  /// Default: 0 (size determined by the size of the first packet sent).
  @ffi.UnsignedInt()
  external int send_buf_size;

  @ffi.Array.multi([2])
  external ffi.Array<UnnamedStruct$7> comp;
}

/// Transport operation types to be reported on \a on_status() callback
enum pj_ice_strans_op {
  /// Initialization (candidate gathering)
  PJ_ICE_STRANS_OP_INIT(0),

  /// Negotiation
  PJ_ICE_STRANS_OP_NEGOTIATION(1),

  /// This operation is used to report failure in keep-alive operation.
  /// Currently it is only used to report TURN Refresh failure.
  PJ_ICE_STRANS_OP_KEEP_ALIVE(2),

  /// IP address change notification from STUN keep-alive operation.
  PJ_ICE_STRANS_OP_ADDR_CHANGE(3);

  final int value;
  const pj_ice_strans_op(this.value);

  static pj_ice_strans_op fromValue(int value) => switch (value) {
    0 => PJ_ICE_STRANS_OP_INIT,
    1 => PJ_ICE_STRANS_OP_NEGOTIATION,
    2 => PJ_ICE_STRANS_OP_KEEP_ALIVE,
    3 => PJ_ICE_STRANS_OP_ADDR_CHANGE,
    _ => throw ArgumentError('Unknown value for pj_ice_strans_op: $value'),
  };
}

/// ICE stream transport's state.
enum pj_ice_strans_state {
  /// ICE stream transport is not created.
  PJ_ICE_STRANS_STATE_NULL(0),

  /// ICE candidate gathering process is in progress.
  PJ_ICE_STRANS_STATE_INIT(1),

  /// ICE stream transport initialization/candidate gathering process is
  /// complete, ICE session may be created on this stream transport.
  PJ_ICE_STRANS_STATE_READY(2),

  /// New session has been created and the session is ready.
  PJ_ICE_STRANS_STATE_SESS_READY(3),

  /// ICE negotiation is in progress.
  PJ_ICE_STRANS_STATE_NEGO(4),

  /// ICE negotiation has completed successfully and media is ready
  /// to be used.
  PJ_ICE_STRANS_STATE_RUNNING(5),

  /// ICE negotiation has completed with failure.
  PJ_ICE_STRANS_STATE_FAILED(6);

  final int value;
  const pj_ice_strans_state(this.value);

  static pj_ice_strans_state fromValue(int value) => switch (value) {
    0 => PJ_ICE_STRANS_STATE_NULL,
    1 => PJ_ICE_STRANS_STATE_INIT,
    2 => PJ_ICE_STRANS_STATE_READY,
    3 => PJ_ICE_STRANS_STATE_SESS_READY,
    4 => PJ_ICE_STRANS_STATE_NEGO,
    5 => PJ_ICE_STRANS_STATE_RUNNING,
    6 => PJ_ICE_STRANS_STATE_FAILED,
    _ => throw ArgumentError('Unknown value for pj_ice_strans_state: $value'),
  };
}

/// STUN and local transport settings for ICE stream transport.
final class pj_ice_strans_stun_cfg extends ffi.Struct {
  /// Address family, IPv4 or IPv6.
  ///
  /// Default value is pj_AF_INET() (IPv4)
  @ffi.Int()
  external int af;

  /// Optional configuration for STUN transport. The default
  /// value will be initialized with #pj_stun_sock_cfg_default().
  external pj_stun_sock_cfg cfg;

  /// Maximum number of host candidates to be added. If the
  /// value is zero, no host candidates will be added.
  ///
  /// Default: 64
  @ffi.UnsignedInt()
  external int max_host_cands;

  /// Number of manual host candidates. This must be equal or less than
  /// \a max_host_cands.
  @ffi.UnsignedInt()
  external int manual_host_cnt;

  /// Optional configuration to manually specify host candidates.
  /// Each candidate will use the same port as the automatic/base host
  /// candidate.
