/// Bitwise flag for SSL certificate verification.
enum pj_ssl_cert_verify_flag_t {
  /// No error in verification.
  PJ_SSL_CERT_ESUCCESS(0),

  /// The issuer certificate cannot be found.
  PJ_SSL_CERT_EISSUER_NOT_FOUND(1),

  /// The certificate is untrusted.
  PJ_SSL_CERT_EUNTRUSTED(2),

  /// The certificate has expired or not yet valid.
  PJ_SSL_CERT_EVALIDITY_PERIOD(4),

  /// One or more fields of the certificate cannot be decoded due to
  /// invalid format.
  PJ_SSL_CERT_EINVALID_FORMAT(8),

  /// The certificate cannot be used for the specified purpose.
  PJ_SSL_CERT_EINVALID_PURPOSE(16),

  /// The issuer info in the certificate does not match to the (candidate)
  /// issuer certificate, e.g: issuer name not match to subject name
  /// of (candidate) issuer certificate.
  PJ_SSL_CERT_EISSUER_MISMATCH(32),

  /// The CRL certificate cannot be found or cannot be read properly.
  PJ_SSL_CERT_ECRL_FAILURE(64),

  /// The certificate has been revoked.
  PJ_SSL_CERT_EREVOKED(128),

  /// The certificate chain length is too long.
  PJ_SSL_CERT_ECHAIN_TOO_LONG(256),

  /// The certificate signature is created using a weak hashing algorithm.
  PJ_SSL_CERT_EWEAK_SIGNATURE(512),

  /// The server identity does not match to any identities specified in
  /// the certificate, e.g: subjectAltName extension, subject common name.
  /// This flag will only be set by application as SSL socket does not
  /// perform server identity verification.
  PJ_SSL_CERT_EIDENTITY_NOT_MATCH(1073741824),

  /// Unknown verification error.
  PJ_SSL_CERT_EUNKNOWN(-2147483648);

  final int value;
  const pj_ssl_cert_verify_flag_t(this.value);

  static pj_ssl_cert_verify_flag_t fromValue(int value) => switch (value) {
    0 => PJ_SSL_CERT_ESUCCESS,
    1 => PJ_SSL_CERT_EISSUER_NOT_FOUND,
    2 => PJ_SSL_CERT_EUNTRUSTED,
    4 => PJ_SSL_CERT_EVALIDITY_PERIOD,
    8 => PJ_SSL_CERT_EINVALID_FORMAT,
    16 => PJ_SSL_CERT_EINVALID_PURPOSE,
    32 => PJ_SSL_CERT_EISSUER_MISMATCH,
    64 => PJ_SSL_CERT_ECRL_FAILURE,
    128 => PJ_SSL_CERT_EREVOKED,
    256 => PJ_SSL_CERT_ECHAIN_TOO_LONG,
    512 => PJ_SSL_CERT_EWEAK_SIGNATURE,
    1073741824 => PJ_SSL_CERT_EIDENTITY_NOT_MATCH,
    -2147483648 => PJ_SSL_CERT_EUNKNOWN,
    _ => throw ArgumentError(
      'Unknown value for pj_ssl_cert_verify_flag_t: $value',
    ),
  };
}

