/// Enumeration of secure socket protocol types.
/// This can be combined using bitwise OR operation.
enum pj_ssl_sock_proto {
  /// Default protocol of backend.
  /// Typically this will be set to all supported non-deprecated protocols,
  /// which, currently is TLSv1.2 and TLSv1.3.
  PJ_SSL_SOCK_PROTO_DEFAULT(0),

  /// SSLv2.0 protocol.
  /// This protocol has been deprecated.
  PJ_SSL_SOCK_PROTO_SSL2(1),

  /// SSLv3.0 protocol.
  /// This protocol has been deprecated.
  PJ_SSL_SOCK_PROTO_SSL3(2),

  /// TLSv1.0 protocol.
  /// This protocol has been deprecated.
  PJ_SSL_SOCK_PROTO_TLS1(4),

  /// TLSv1.1 protocol.
  /// This protocol has been deprecated.
  PJ_SSL_SOCK_PROTO_TLS1_1(8),

  /// TLSv1.2 protocol.
  PJ_SSL_SOCK_PROTO_TLS1_2(16),

  /// TLSv1.3 protocol.
  PJ_SSL_SOCK_PROTO_TLS1_3(32),

  /// This protocol has been deprecated.
  PJ_SSL_SOCK_PROTO_SSL23(65535),

  /// DTLSv1.0 protocol.
  PJ_SSL_SOCK_PROTO_DTLS1(65536);

  /// This will enable all the backend's supported protocols.
  static const PJ_SSL_SOCK_PROTO_ALL = PJ_SSL_SOCK_PROTO_SSL23;

  final int value;
  const pj_ssl_sock_proto(this.value);

  static pj_ssl_sock_proto fromValue(int value) => switch (value) {
    0 => PJ_SSL_SOCK_PROTO_DEFAULT,
    1 => PJ_SSL_SOCK_PROTO_SSL2,
    2 => PJ_SSL_SOCK_PROTO_SSL3,
    4 => PJ_SSL_SOCK_PROTO_TLS1,
    8 => PJ_SSL_SOCK_PROTO_TLS1_1,
    16 => PJ_SSL_SOCK_PROTO_TLS1_2,
    32 => PJ_SSL_SOCK_PROTO_TLS1_3,
    65535 => PJ_SSL_SOCK_PROTO_SSL23,
    65536 => PJ_SSL_SOCK_PROTO_DTLS1,
    _ => throw ArgumentError('Unknown value for pj_ssl_sock_proto: $value'),
  };

  @override
  String toString() {
    if (this == PJ_SSL_SOCK_PROTO_SSL23)
      return "pj_ssl_sock_proto.PJ_SSL_SOCK_PROTO_SSL23, pj_ssl_sock_proto.PJ_SSL_SOCK_PROTO_ALL";
