    1 => PJ_STUN_BINDING_REQUEST,
    257 => PJ_STUN_BINDING_RESPONSE,
    273 => PJ_STUN_BINDING_ERROR_RESPONSE,
    17 => PJ_STUN_BINDING_INDICATION,
    2 => PJ_STUN_SHARED_SECRET_REQUEST,
    258 => PJ_STUN_SHARED_SECRET_RESPONSE,
    274 => PJ_STUN_SHARED_SECRET_ERROR_RESPONSE,
    3 => PJ_STUN_ALLOCATE_REQUEST,
    259 => PJ_STUN_ALLOCATE_RESPONSE,
    275 => PJ_STUN_ALLOCATE_ERROR_RESPONSE,
    4 => PJ_STUN_REFRESH_REQUEST,
    260 => PJ_STUN_REFRESH_RESPONSE,
    276 => PJ_STUN_REFRESH_ERROR_RESPONSE,
    22 => PJ_STUN_SEND_INDICATION,
    23 => PJ_STUN_DATA_INDICATION,
    8 => PJ_STUN_CREATE_PERM_REQUEST,
    264 => PJ_STUN_CREATE_PERM_RESPONSE,
    280 => PJ_STUN_CREATE_PERM_ERROR_RESPONSE,
    9 => PJ_STUN_CHANNEL_BIND_REQUEST,
    265 => PJ_STUN_CHANNEL_BIND_RESPONSE,
    281 => PJ_STUN_CHANNEL_BIND_ERROR_RESPONSE,
    10 => PJ_STUN_CONNECT_REQUEST,
    11 => PJ_STUN_CONNECTION_BIND_REQUEST,
    28 => PJ_STUN_CONNECTION_ATTEMPT_INDICATION,
