  /// should return PJ_TRUE to let the STUN socket operation
  /// continues.
  external ffi.Pointer<
    ffi.NativeFunction<
      pj_bool_t Function(
        ffi.Pointer<pj_stun_sock> stun_sock,
        ffi.UnsignedInt op,
        pj_status_t status,
