    on_rx_data,
    required ffi.Pointer<
      ffi.NativeFunction<
        pj_bool_t Function(
          ffi.Pointer<pj_stun_sock> stun_sock,
          ffi.Pointer<pj_ioqueue_op_key_t> send_key,
          pj_ssize_t sent,
        )
      >
    >
    on_data_sent,
    required ffi.Pointer<
      ffi.NativeFunction<
        pj_bool_t Function(
          ffi.Pointer<pj_stun_sock> stun_sock,
          ffi.UnsignedInt op,
          pj_status_t status,
        )
