final class pj_stun_uint_attr extends ffi.Struct {
  /// Standard STUN attribute header.
  external pj_stun_attr_hdr hdr;

  /// The 32bit value, in host byte order.
  @pj_uint32_t()
  external int value;
}

/// This describes STUN UNKNOWN-ATTRIBUTES attribute.
/// The UNKNOWN-ATTRIBUTES attribute is present only in an error response
/// when the response code in the ERROR-CODE attribute is 420.
/// The attribute contains a list of 16 bit values, each of which
/// represents an attribute type that was not understood by the server.
/// If the number of unknown attributes is an odd number, one of the
/// attributes MUST be repeated in the list, so that the total length of
/// the list is a multiple of 4 bytes.
final class pj_stun_unknown_attr extends ffi.Struct {
  /// Standard STUN attribute header.
  external pj_stun_attr_hdr hdr;

  /// Number of unknown attributes in the array.
  @ffi.UnsignedInt()
  external int attr_count;

  /// Array of unknown attribute IDs.
  @ffi.Array.multi([16])
  external ffi.Array<pj_uint16_t> attrs;
}

/// This describes the USE-CANDIDATE attribute from draft-ietf-mmusic-ice-13.
/// The USE-CANDIDATE attribute indicates that the candidate pair
/// resulting from this check should be used for transmission of media.
/// The attribute has no content (the Length field of the attribute is
/// zero); it serves as a flag.
typedef pj_stun_use_candidate_attr = pj_stun_empty_attr;

/// This describes STUN USERNAME attribute.
/// The USERNAME attribute is used for message integrity.  It identifies
/// the shared secret used in the message integrity check.  Consequently,
/// the USERNAME MUST be included in any request that contains the
/// MESSAGE-INTEGRITY attribute.
typedef pj_stun_username_attr = pj_stun_string_attr;

/// This describes STUN XOR-MAPPED-ADDRESS attribute (which has the same
/// format as STUN MAPPED-ADDRESS attribute).
/// The XOR-MAPPED-ADDRESS attribute is present in responses.  It
/// provides the same information that would present in the MAPPED-
/// ADDRESS attribute but because the NAT's public IP address is
/// obfuscated through the XOR function, STUN messages are able to pass
/// through NATs which would otherwise interfere with STUN.
typedef pj_stun_xor_mapped_addr_attr = pj_stun_sockaddr_attr;

/// This describes the STUN XOR-PEER-ADDRESS attribute.
/// The XOR-PEER-ADDRESS specifies the address and port of the peer as seen
/// from the TURN server.  It is encoded in the same way as XOR-MAPPED-
/// ADDRESS.
typedef pj_stun_xor_peer_addr_attr = pj_stun_sockaddr_attr;

/// This describes the XOR-REFLECTED-FROM attribute, as described by
/// draft-macdonald-behave-nat-behavior-discovery-00.
/// The XOR-REFLECTED-FROM attribute is used in place of the REFLECTED-
/// FROM attribute.  It provides the same information, but because the
/// NAT's public address is obfuscated through the XOR function, It can
/// pass through a NAT that would otherwise attempt to translate it to
/// the private network address.  XOR-REFLECTED-FROM has identical syntax
/// to XOR-MAPPED-ADDRESS.
typedef pj_stun_xor_reflected_from_attr = pj_stun_sockaddr_attr;

/// This describes the STUN XOR-RELAYED-ADDRESS attribute. The
/// XOR-RELAYED-ADDRESS is present in Allocate responses.  It specifies the
/// address and port that the server allocated to the client.  It is
/// encoded in the same way as XOR-MAPPED-ADDRESS.
typedef pj_stun_xor_relayed_addr_attr = pj_stun_sockaddr_attr;

/// This structure declares Symbian OS specific parameters that can be
/// specified when calling #pj_symbianos_set_params().
final class pj_symbianos_params extends ffi.Struct {
  /// Optional RSocketServ instance to be used by PJLIB. If this
  /// value is NULL, PJLIB will create a new RSocketServ instance
  /// when pj_init() is called.
  external ffi.Pointer<ffi.Void> rsocketserv;

  /// Optional RConnection instance to be used by PJLIB when creating
  /// sockets. If this value is NULL, no RConnection will be
  /// specified when creating sockets.
  external ffi.Pointer<ffi.Void> rconnection;

  /// Optional RHostResolver instance to be used by PJLIB. If this value
  /// is NULL, a new RHostResolver instance will be created when
  /// pj_init() is called.
  external ffi.Pointer<ffi.Void> rhostresolver;

  /// Optional RHostResolver for IPv6 instance to be used by PJLIB.
  /// If this value is NULL, a new RHostResolver instance will be created
  /// when pj_init() is called.
  external ffi.Pointer<ffi.Void> rhostresolver6;

  static ffi.Pointer<pj_symbianos_params> $allocate(
    ffi.Allocator $allocator, {
    required ffi.Pointer<ffi.Void> rsocketserv,
    required ffi.Pointer<ffi.Void> rconnection,
    required ffi.Pointer<ffi.Void> rhostresolver,
    required ffi.Pointer<ffi.Void> rhostresolver6,
  }) => $allocator<pj_symbianos_params>()
    ..ref.rsocketserv = rsocketserv
    ..ref.rconnection = rconnection
    ..ref.rhostresolver = rhostresolver
    ..ref.rhostresolver6 = rhostresolver6;
}

/// The callback function type to be called by the scanner when it encounters
/// syntax error.
///
/// @param scanner       The scanner instance that calls the callback .
typedef pj_syn_err_func_ptr =
    ffi.Pointer<ffi.NativeFunction<pj_syn_err_func_ptrFunction>>;
typedef pj_syn_err_func_ptrFunction = ffi.Void Function(
  ffi.Pointer<pj_scanner> scanner,
);
typedef Dartpj_syn_err_func_ptrFunction = void Function(
  ffi.Pointer<pj_scanner> scanner,
);

/// This structure contains information about the system. Use #pj_get_sys_info()
/// to obtain the system information.
final class pj_sys_info extends ffi.Struct {
  /// Null terminated string containing processor information (e.g. "i386",
  /// "x86_64"). It may contain empty string if the value cannot be obtained.
  external pj_str_t machine;

  /// Null terminated string identifying the system operation (e.g. "Linux",
  /// "win32", "wince"). It may contain empty string if the value cannot be
  /// obtained.
  external pj_str_t os_name;

  /// A number containing the operating system version number. By convention,
  /// this field is divided into four bytes, where the highest order byte
  /// contains the most major version of the OS, the next less significant
  /// byte contains the less major version, and so on. How the OS version
  /// number is mapped into these four bytes would be specific for each OS.
  /// For example, Linux-2.6.32-28 would yield "os_ver" value of 0x0206201c,
  /// while for Windows 7 it will be 0x06010000 (because dwMajorVersion is
  /// 6 and dwMinorVersion is 1 for Windows 7).
  ///
  /// This field may contain zero if the OS version cannot be obtained.
  @pj_uint32_t()
  external int os_ver;

  /// Null terminated string identifying the SDK name that is used to build
  /// the library (e.g. "glibc", "uclibc", "msvc", "wince"). It may contain
  /// empty string if the value cannot eb obtained.
  external pj_str_t sdk_name;

  /// A number containing the SDK version, using the numbering convention as
  /// the "os_ver" field. The value will be zero if the version cannot be
  /// obtained.
  @pj_uint32_t()
  external int sdk_ver;

  /// A longer null terminated string identifying the underlying system with
  /// as much information as possible.
  external pj_str_t info;

  /// Other flags containing system specific information. The value is
  /// bitmask of #pj_sys_info_flag constants.
  @pj_uint32_t()
  external int flags;
}

/// These enumeration contains constants to indicate support of miscellaneous
/// system features. These will go in "flags" field of #pj_sys_info structure.
enum pj_sys_info_flag {
  /// Support for Apple iOS background feature.
  PJ_SYS_HAS_IOS_BG(1);

  final int value;
  const pj_sys_info_flag(this.value);

  static pj_sys_info_flag fromValue(int value) => switch (value) {
    1 => PJ_SYS_HAS_IOS_BG,
    _ => throw ArgumentError('Unknown value for pj_sys_info_flag: $value'),
  };
}

/// A test case is unit-test object to perform test against a user defined
/// function.
final class pj_test_case extends ffi.Struct {
  external ffi.Pointer<pj_test_case> prev;

  external ffi.Pointer<pj_test_case> next;

  /// Test name
  @ffi.Array.multi([32])
  external ffi.Array<ffi.Char> obj_name;

  /// The test function to be called to perform the test. By convention, the
  /// function must return zero for the test to be considered successful,
  /// non-zero on failure, and MUST NEVER return PJ_EPENDING, otherwise the
  /// return value will be silently changed to -12345.
  external ffi.Pointer<
    ffi.NativeFunction<ffi.Int Function(ffi.Pointer<ffi.Void>)>
  >
  test_func;

  /// Argument to be passed to the test function
  external ffi.Pointer<ffi.Void> arg;

  /// Flags, combination of pj_test_flag constants
  @ffi.UnsignedInt()
  external int flags;

  /// Circular buffer for logging
  external pj_fifobuf_t fb;

  /// Parameters
  external pj_test_case_param prm;

  /// The return value of the test function. Zero indicates success. Initially
  /// the value is PJ_EPENDING before the test is run.
  @ffi.Int()
  external int result;

  /// List of saved logging messages
  external pj_test_log_item logs;

  /// Pointer to the runner running this test case
  external ffi.Pointer<pj_test_runner> runner;

  /// Start time
  external pj_timestamp start_time;

  /// End time
  external pj_timestamp end_time;
}

/// Bitwise constants that can be used in test case flags (see
/// pj_test_case_init()).
enum pj_test_case_flag {
  /// Do not allow other test cases to run while this test case is running.
  /// Note this only makes sense for test runners that support worker
  /// threads. Basic runner will always run test cases serially.
  PJ_TEST_EXCLUSIVE(1),

  /// Specify that the test function must be called without argument.
  /// This is mainly for backward compatibility with existing PJ test
  /// functions which take no argument.
  PJ_TEST_FUNC_NO_ARG(2),

  /// Write the original log at the time it is called instead of pooling
  /// the logs to be printed after all tests finish.
  PJ_TEST_LOG_NO_CACHE(4),

  /// Keep this test case in front of the list when shuffling the test
  /// cases.
  PJ_TEST_KEEP_FIRST(8),

  /// Keep this test case in last in the list when shuffling the test
  /// cases.
  PJ_TEST_KEEP_LAST(16);

  final int value;
  const pj_test_case_flag(this.value);

  static pj_test_case_flag fromValue(int value) => switch (value) {
    1 => PJ_TEST_EXCLUSIVE,
    2 => PJ_TEST_FUNC_NO_ARG,
    4 => PJ_TEST_LOG_NO_CACHE,
    8 => PJ_TEST_KEEP_FIRST,
    16 => PJ_TEST_KEEP_LAST,
    _ => throw ArgumentError('Unknown value for pj_test_case_flag: $value'),
  };
}

/// Additional parameters for creating test case. Use
/// pj_test_case_param_default() to initialize this structure.
final class pj_test_case_param extends ffi.Struct {
  /// Custom log level for this test case, to filter out logs that are more
  /// detail than this level. Default is 6, meaning it will accept all log
  /// levels.
  @ffi.Int()
  external int log_level;

  static ffi.Pointer<pj_test_case_param> $allocate(
    ffi.Allocator $allocator, {
    required int log_level,
  }) => $allocator<pj_test_case_param>()..ref.log_level = log_level;
}

/// An internal structure to represent one logging item that is saved
/// inside pj_test_case.
final class pj_test_log_item extends ffi.Struct {
  external ffi.Pointer<pj_test_log_item> prev;

  external ffi.Pointer<pj_test_log_item> next;

  /// level
  @ffi.Int()
  external int level;

  /// len
  @ffi.Int()
  external int len;

  /// The log message. The actual buffer is longer.
  @ffi.Array.multi([1])
  external ffi.Array<ffi.Char> msg;
}

/// This structure represents a test runner. Currently there are two types
/// of test runners, the basic runner and text runner. The basic runner is the
/// simplest test runner that can be used without pool and threads, and can be
/// created with pj_test_init_basic_runner(). The text runner is more powerful
/// since it supports worker threads, and it is mostly suitable for console
/// based environments. It is created with pj_test_create_text_runner().
final class pj_test_runner extends ffi.Struct {
  /// Parameters
  external pj_test_runner_param prm;

  /// The test suite being run
  external ffi.Pointer<pj_test_suite> suite;

  /// Saving the original log writer
  external ffi.Pointer<pj_log_func> orig_log_writer;

  /// Number of tests
  @ffi.UnsignedInt()
  external int ntests;

  /// Number of completed tests
  @ffi.UnsignedInt()
  external int nruns;

  /// Stopping
  @pj_bool_t()
  external int stopping;

  /// main method
  external ffi.Pointer<
    ffi.NativeFunction<ffi.Void Function(ffi.Pointer<pj_test_runner>)>
  >
  main;

  /// callback when test case completes. Default is to write to log
  external ffi.Pointer<
    ffi.NativeFunction<
      ffi.Void Function(ffi.Pointer<pj_test_runner>, ffi.Pointer<pj_test_case>)
    >
  >
  on_test_complete;

  /// destroy method
  external ffi.Pointer<
    ffi.NativeFunction<ffi.Void Function(ffi.Pointer<pj_test_runner>)>
  >
  destroy;
}

/// Test runner parameters. Use pj_test_runner_param_default() to initialize
/// this structure.
final class pj_test_runner_param extends ffi.Struct {
  /// Stop the test on error (default: false)
  @pj_bool_t()
  external int stop_on_error;

  /// Number of worker threads. Set to zero to disable parallel testings.
  /// Only applicable to test text runner. Default is 1 if multithreading
  /// is available.
  @ffi.UnsignedInt()
  external int nthreads;

  /// 0: only display test name and result after test completion (default)
  /// 1: display test name test when starting and finishing a test
  @ffi.UnsignedInt()
  external int verbosity;

  static ffi.Pointer<pj_test_runner_param> $allocate(
    ffi.Allocator $allocator, {
    required int stop_on_error,
    required int nthreads,
    required int verbosity,
  }) => $allocator<pj_test_runner_param>()
    ..ref.stop_on_error = stop_on_error
    ..ref.nthreads = nthreads
    ..ref.verbosity = verbosity;
}

/// Option to select tests (e.g. in pj_test_dump_log_messages())
enum pj_test_select_tests {
  /// Select no test
  PJ_TEST_NO_TEST(0),

  /// Select only failed tests
  PJ_TEST_FAILED_TESTS(1),

  /// Select only successful tests
  PJ_TEST_SUCCESSFUL_TESTS(2),

  /// Select all tests
  PJ_TEST_ALL_TESTS(3),

  /// No header/footer separator
  PJ_TEST_NO_HEADER_FOOTER(4);

  final int value;
  const pj_test_select_tests(this.value);

  static pj_test_select_tests fromValue(int value) => switch (value) {
    0 => PJ_TEST_NO_TEST,
    1 => PJ_TEST_FAILED_TESTS,
    2 => PJ_TEST_SUCCESSFUL_TESTS,
    3 => PJ_TEST_ALL_TESTS,
    4 => PJ_TEST_NO_HEADER_FOOTER,
    _ => throw ArgumentError('Unknown value for pj_test_select_tests: $value'),
  };
}

/// Test statistics. Collect the statistics after the test runner finishes
/// with pj_test_get_stat().
final class pj_test_stat extends ffi.Struct {
  /// Total duration
  external pj_time_val duration;

  /// Total number of tests in the test suite
  @ffi.UnsignedInt()
  external int ntests;

  /// Number of tests run
  @ffi.UnsignedInt()
  external int nruns;

  /// Number of failed tests
  @ffi.UnsignedInt()
  external int nfailed;

  /// Array of failed test names. Be careful that the number elements are
  /// fixed, hence it may not be able to store all failed test names (in case
  /// nfailed is more than the capacity, not all failed test names will be
  /// stored, hence be careful in the loop).
  @ffi.Array.multi([32])
  external ffi.Array<ffi.Pointer<ffi.Char>> failed_names;
}

/// Test suite is a collection of test cases.
final class pj_test_suite extends ffi.Struct {
  /// List of tests
  external pj_test_case tests;

  /// Start time
  external pj_timestamp start_time;

  /// End time
  external pj_timestamp end_time;
}

/// Thread creation flags:
/// - PJ_THREAD_SUSPENDED: specify that the thread should be created suspended.
enum pj_thread_create_flags {
  PJ_THREAD_SUSPENDED(1);

  final int value;
  const pj_thread_create_flags(this.value);

  static pj_thread_create_flags fromValue(int value) => switch (value) {
    1 => PJ_THREAD_SUSPENDED,
    _ => throw ArgumentError(
      'Unknown value for pj_thread_create_flags: $value',
    ),
  };
}

/// Type of thread entry function.
typedef pj_thread_proc =
    ffi.NativeFunction<ffi.Int Function(ffi.Pointer<ffi.Void>)>;

final class pj_thread_t extends ffi.Opaque {}

/// Representation of time value in this library.
/// This type can be used to represent either an interval or a specific time
/// or date.
final class pj_time_val extends ffi.Struct {
  /// The seconds part of the time.
  @ffi.Long()
  external int sec;

  /// The miliseconds fraction of the time.
  @ffi.Long()
  external int msec;

  static ffi.Pointer<pj_time_val> $allocate(
    ffi.Allocator $allocator, {
    required int sec,
    required int msec,
  }) => $allocator<pj_time_val>()
    ..ref.sec = sec
    ..ref.msec = msec;
}

/// This structure represents an entry to the timer.
final class pj_timer_entry extends ffi.Struct {
  /// User data to be associated with this entry.
  /// Applications normally will put the instance of object that
  /// owns the timer entry in this field.
  external ffi.Pointer<ffi.Void> user_data;

  /// Arbitrary ID assigned by the user/owner of this entry.
  /// Applications can use this ID to distinguish multiple
  /// timer entries that share the same callback and user_data.
  @ffi.Int()
  external int id;

  /// Callback to be called when the timer expires.
  external ffi.Pointer<pj_timer_heap_callback> cb;

  /// Internal unique timer ID, which is assigned by the timer heap.
  /// Positive values indicate that the timer entry is running,
  /// while -1 means that it's not. Any other value may indicate that it
  /// hasn't been properly initialised or is in a bad state.
  /// Application should not touch this ID.
  @pj_timer_id_t()
  external int _timer_id;

  static ffi.Pointer<pj_timer_entry> $allocate(
    ffi.Allocator $allocator, {
    required ffi.Pointer<ffi.Void> user_data,
    required int id,
    required ffi.Pointer<pj_timer_heap_callback> cb,
    required int $timer_id,
  }) => $allocator<pj_timer_entry>()
    ..ref.user_data = user_data
    ..ref.id = id
    ..ref.cb = cb
    ..ref._timer_id = $timer_id;
}

/// The type of callback function to be called by timer scheduler when a timer
/// has expired.
///
/// @param timer_heap    The timer heap.
/// @param entry         Timer entry which timer's has expired.
typedef pj_timer_heap_callback =
    ffi.NativeFunction<
      ffi.Void Function(
        ffi.Pointer<pj_timer_heap_t> timer_heap,
        ffi.Pointer<pj_timer_entry> entry,
      )
    >;

final class pj_timer_heap_t extends ffi.Opaque {}

/// The type for internal timer ID.
typedef pj_timer_id_t = ffi.Int;
typedef Dartpj_timer_id_t = int;

/// This structure represents high resolution (64bit) time value. The time
/// values represent time in cycles, which is retrieved by calling
/// #pj_get_timestamp().
final class pj_timestamp extends ffi.Union {
  /// < The 64-bit value as two 32-bit values.
  external UnnamedStruct$2 u32;

  /// < The whole 64-bit value, where available.
  @pj_uint64_t()
  external int u64;
}

/// Allocation parameter, which can be given when application calls
/// pj_turn_session_alloc() to allocate relay address in the TURN server.
/// Application should call pj_turn_alloc_param_default() to initialize
/// this structure with the default values.
final class pj_turn_alloc_param extends ffi.Struct {
  /// The requested BANDWIDTH. Default is zero to not request any
  /// specific bandwidth. Note that this attribute has been deprecated
  /// after TURN-08 draft, hence application should only use this
  /// attribute when talking to TURN-07 or older version.
  @ffi.Int()
  external int bandwidth;

  /// The requested LIFETIME. Default is zero to not request any
  /// explicit allocation lifetime.
  @ffi.Int()
  external int lifetime;

  /// If set to non-zero, the TURN session will periodically send blank
  /// Send Indication every PJ_TURN_KEEP_ALIVE_SEC to refresh local
  /// NAT bindings. Default is zero.
  @ffi.Int()
  external int ka_interval;

  /// The requested ADDRESS-FAMILY. Default is zero to request relay with
  /// address family matched to the one specified in TURN session creation.
  /// Valid values are zero, pj_AF_INET(), and pj_AF_INET6().
  ///
  /// Default value is zero.
  @ffi.Int()
  external int af;

  /// Type of connection to from TURN server to peer. Supported values are
  /// PJ_TURN_TP_UDP (RFC 5766) and PJ_TURN_TP_TCP (RFC 6062)
  ///
  /// Default is PJ_TURN_TP_UDP.
  @ffi.UnsignedInt()
  external int peer_conn_typeAsInt;

  pj_turn_tp_type get peer_conn_type =>
      pj_turn_tp_type.fromValue(peer_conn_typeAsInt);
  set peer_conn_type(pj_turn_tp_type value) =>
      peer_conn_typeAsInt = value.value;

  static ffi.Pointer<pj_turn_alloc_param> $allocate(
    ffi.Allocator $allocator, {
    required int bandwidth,
    required int lifetime,
    required int ka_interval,
    required int af,
    required pj_turn_tp_type peer_conn_type,
  }) => $allocator<pj_turn_alloc_param>()
    ..ref.bandwidth = bandwidth
    ..ref.lifetime = lifetime
    ..ref.ka_interval = ka_interval
    ..ref.af = af
    ..ref.peer_conn_type = peer_conn_type;
}

/// This structure ChannelData header. All the fields are in network byte
/// order when it's on the wire.
@ffi.Packed(1)
final class pj_turn_channel_data extends ffi.Struct {
  /// < Channel number.
  @pj_uint16_t()
  external int ch_number;

  /// < Payload length.
  @pj_uint16_t()
  external int length;

  static ffi.Pointer<pj_turn_channel_data> $allocate(
    ffi.Allocator $allocator, {
    required int ch_number,
    required int length,
  }) => $allocator<pj_turn_channel_data>()
    ..ref.ch_number = ch_number
    ..ref.length = length;
}

final class pj_turn_session extends ffi.Opaque {}

/// Callback to receive events from TURN session.
final class pj_turn_session_cb extends ffi.Struct {
  /// This callback will be called by the TURN session whenever it
  /// needs to send data or outgoing messages. Since the TURN session
  /// doesn't have a socket on its own, this callback must be implemented.
  ///
  /// If the callback \a on_stun_send_pkt() is implemented, outgoing
  /// messages will use that callback instead.
  ///
  /// @param sess      The TURN session.
  /// @param pkt       The packet/data to be sent.
  /// @param pkt_len   Length of the packet/data.
  /// @param dst_addr  Destination address of the packet.
  /// @param addr_len  Length of the destination address.
  ///
  /// @return          The callback should return the status of the
  /// send operation.
  external ffi.Pointer<
    ffi.NativeFunction<
      pj_status_t Function(
        ffi.Pointer<pj_turn_session> sess,
        ffi.Pointer<pj_uint8_t> pkt,
        ffi.UnsignedInt pkt_len,
        ffi.Pointer<pj_sockaddr_t> dst_addr,
        ffi.UnsignedInt addr_len,
      )
    >
  >
  on_send_pkt;

  /// This callback will be called by the TURN session whenever it
  /// needs to send outgoing STUN requests/messages for TURN signalling
  /// purposes (data sending will not invoke this callback). If this
  /// callback is not implemented, the callback \a on_send_pkt()
  /// will be called instead.
  ///
  /// @param sess      The TURN session.
  /// @param pkt       The packet/data to be sent.
  /// @param pkt_len   Length of the packet/data.
  /// @param dst_addr  Destination address of the packet.
  /// @param addr_len  Length of the destination address.
  ///
  /// @return          The callback should return the status of the
  /// send operation.
  external ffi.Pointer<
    ffi.NativeFunction<
      pj_status_t Function(
        ffi.Pointer<pj_turn_session> sess,
        ffi.Pointer<pj_uint8_t> pkt,
        ffi.UnsignedInt pkt_len,
        ffi.Pointer<pj_sockaddr_t> dst_addr,
        ffi.UnsignedInt addr_len,
      )
    >
  >
  on_stun_send_pkt;

  /// Notification when peer address has been bound successfully to
  /// a channel number.
  ///
  /// This callback is optional since the nature of this callback is
  /// for information only.
  ///
  /// @param sess      The TURN session.
  /// @param peer_addr The peer address.
  /// @param addr_len  Length of the peer address.
  /// @param ch_num    The channel number associated with this peer address.
  external ffi.Pointer<
    ffi.NativeFunction<
      ffi.Void Function(
        ffi.Pointer<pj_turn_session> sess,
