/// This structure describes TURN session info.
final class pj_turn_session_info extends ffi.Struct {
  /// Session state.
  @ffi.UnsignedInt()
  external int stateAsInt;

  pj_turn_state_t get state => pj_turn_state_t.fromValue(stateAsInt);
  set state(pj_turn_state_t value) => stateAsInt = value.value;

  /// Last error (if session was terminated because of error)
  @pj_status_t()
  external int last_status;

  /// Type of connection to the TURN server.
  @ffi.UnsignedInt()
  external int conn_typeAsInt;

  pj_turn_tp_type get conn_type => pj_turn_tp_type.fromValue(conn_typeAsInt);
  set conn_type(pj_turn_tp_type value) => conn_typeAsInt = value.value;

  /// The selected TURN server address.
  external pj_sockaddr server;

  /// Mapped address, as reported by the TURN server.
  external pj_sockaddr mapped_addr;

  /// The relay address
  external pj_sockaddr relay_addr;

  /// Current seconds before allocation expires.
  @ffi.Int()
  external int lifetime;
}

