final class pj_turn_sock extends ffi.Opaque {}

/// This structure contains callbacks that will be called by the TURN
/// transport.
final class pj_turn_sock_cb extends ffi.Struct {
  /// Notification when incoming data has been received from the remote
  /// peer via the TURN server. The data reported in this callback will
  /// be the exact data as sent by the peer (e.g. the TURN encapsulation
  /// such as Data Indication or ChannelData will be removed before this
  /// function is called).
  ///
  /// @param turn_sock     The TURN client transport.
  /// @param data          The data as received from the peer.
  /// @param data_len      Length of the data.
  /// @param peer_addr     The peer address.
  /// @param addr_len      The length of the peer address.
  external ffi.Pointer<
    ffi.NativeFunction<
      ffi.Void Function(
        ffi.Pointer<pj_turn_sock> turn_sock,
        ffi.Pointer<ffi.Void> pkt,
        ffi.UnsignedInt pkt_len,
        ffi.Pointer<pj_sockaddr_t> peer_addr,
        ffi.UnsignedInt addr_len,
      )
    >
  >
  on_rx_data;

  /// Notifification when asynchronous send operation has completed.
  ///
  /// @param turn_sock     The TURN transport.
  /// @param sent          If value is positive non-zero it indicates the
  /// number of data sent. When the value is negative,
  /// it contains the error code which can be retrieved
  /// by negating the value (i.e. status=-sent).
  ///
  /// @return              Application should normally return PJ_TRUE to let
  /// the TURN transport continue its operation. However
  /// it must return PJ_FALSE if it has destroyed the
  /// TURN transport in this callback.
  external ffi.Pointer<
    ffi.NativeFunction<
      pj_bool_t Function(ffi.Pointer<pj_turn_sock> sock, pj_ssize_t sent)
    >
  >
  on_data_sent;

  /// Notification when TURN session state has changed. Application should
  /// implement this callback to monitor the progress of the TURN session.
  ///
  /// @param turn_sock     The TURN client transport.
  /// @param old_state     Previous state.
  /// @param new_state     Current state.
  external ffi.Pointer<
    ffi.NativeFunction<
      ffi.Void Function(
        ffi.Pointer<pj_turn_sock> turn_sock,
        ffi.UnsignedInt old_state,
        ffi.UnsignedInt new_state,
      )
    >
  >
  on_state;

  /// Notification when TURN client received a ConnectionAttempt Indication
  /// from the TURN server, which indicates that peer initiates a TCP
  /// connection to allocated slot in the TURN server. Application should
  /// implement this callback if it uses RFC 6062 (TURN TCP allocations),
  /// otherwise TURN client will automatically accept it.
  ///
  /// If application accepts the peer connection attempt (i.e: by returning
  /// PJ_SUCCESS or not implementing this callback), the TURN socket will
  /// initiate a new connection to the TURN server and send ConnectionBind
  /// request, and eventually will notify application via
  /// on_connection_status callback, if implemented.
  ///
  /// @param turn_sock     The TURN client transport.
  /// @param conn_id       The connection ID assigned by TURN server.
  /// @param peer_addr     Peer address that tried to connect to the
  /// TURN server.
  /// @param addr_len      Length of the peer address.
  ///
  /// @return              The callback must return PJ_SUCCESS to accept
  /// the connection attempt.
  external ffi.Pointer<
    ffi.NativeFunction<
      pj_status_t Function(
        ffi.Pointer<pj_turn_sock> turn_sock,
        pj_uint32_t conn_id,
        ffi.Pointer<pj_sockaddr_t> peer_addr,
        ffi.UnsignedInt addr_len,
      )
    >
  >
  on_connection_attempt;

  /// Notification for initiated TCP data connection to peer (RFC 6062),
  /// for example after peer connection attempt is accepted.
  ///
  /// @param turn_sock     The TURN client transport.
  /// @param status        The status code.
  /// @param conn_id       The connection ID.
  /// @param peer_addr     Peer address.
  /// @param addr_len      Length of the peer address.
  external ffi.Pointer<
    ffi.NativeFunction<
      ffi.Void Function(
        ffi.Pointer<pj_turn_sock> turn_sock,
        pj_status_t status,
        pj_uint32_t conn_id,
        ffi.Pointer<pj_sockaddr_t> peer_addr,
        ffi.UnsignedInt addr_len,
      )
    >
  >
  on_connection_status;

  static ffi.Pointer<pj_turn_sock_cb> $allocate(
    ffi.Allocator $allocator, {
    required ffi.Pointer<
      ffi.NativeFunction<
        ffi.Void Function(
          ffi.Pointer<pj_turn_sock> turn_sock,
          ffi.Pointer<ffi.Void> pkt,
          ffi.UnsignedInt pkt_len,
          ffi.Pointer<pj_sockaddr_t> peer_addr,
          ffi.UnsignedInt addr_len,
        )
      >
    >
    on_rx_data,
    required ffi.Pointer<
      ffi.NativeFunction<
        pj_bool_t Function(ffi.Pointer<pj_turn_sock> sock, pj_ssize_t sent)
      >
    >
    on_data_sent,
    required ffi.Pointer<
      ffi.NativeFunction<
        ffi.Void Function(
          ffi.Pointer<pj_turn_sock> turn_sock,
          ffi.UnsignedInt old_state,
          ffi.UnsignedInt new_state,
        )
      >
    >
    on_state,
    required ffi.Pointer<
      ffi.NativeFunction<
        pj_status_t Function(
          ffi.Pointer<pj_turn_sock> turn_sock,
          pj_uint32_t conn_id,
          ffi.Pointer<pj_sockaddr_t> peer_addr,
          ffi.UnsignedInt addr_len,
        )
      >
    >
    on_connection_attempt,
    required ffi.Pointer<
      ffi.NativeFunction<
        ffi.Void Function(
          ffi.Pointer<pj_turn_sock> turn_sock,
          pj_status_t status,
          pj_uint32_t conn_id,
          ffi.Pointer<pj_sockaddr_t> peer_addr,
          ffi.UnsignedInt addr_len,
        )
      >
    >
    on_connection_status,
  }) => $allocator<pj_turn_sock_cb>()
    ..ref.on_rx_data = on_rx_data
    ..ref.on_data_sent = on_data_sent
    ..ref.on_state = on_state
    ..ref.on_connection_attempt = on_connection_attempt
    ..ref.on_connection_status = on_connection_status;
}

/// This structure describes options that can be specified when creating
/// the TURN socket. Application should call #pj_turn_sock_cfg_default()
/// to initialize this structure with its default values before using it.
final class pj_turn_sock_cfg extends ffi.Struct {
  /// The group lock to be used by the STUN socket. If NULL, the STUN socket
  /// will create one internally.
  ///
  /// Default: NULL
  external ffi.Pointer<pj_grp_lock_t> grp_lock;

  /// Packet buffer size.
  ///
  /// Default value is PJ_TURN_MAX_PKT_LEN.
  @ffi.UnsignedInt()
  external int max_pkt_size;

  /// QoS traffic type to be set on this transport. When application wants
  /// to apply QoS tagging to the transport, it's preferable to set this
  /// field rather than \a qos_param fields since this is more portable.
  ///
  /// Default value is PJ_QOS_TYPE_BEST_EFFORT.
  @ffi.UnsignedInt()
  external int qos_typeAsInt;

  pj_qos_type get qos_type => pj_qos_type.fromValue(qos_typeAsInt);
  set qos_type(pj_qos_type value) => qos_typeAsInt = value.value;

  /// Set the low level QoS parameters to the transport. This is a lower
  /// level operation than setting the \a qos_type field and may not be
  /// supported on all platforms.
  ///
  /// By default all settings in this structure are not set.
  external pj_qos_params qos_params;

  /// Specify if STUN socket should ignore any errors when setting the QoS
  /// traffic type/parameters.
  ///
  /// Default: PJ_TRUE
  @pj_bool_t()
  external int qos_ignore_error;

  /// Specify the interface where the socket should be bound to. If the
  /// address is zero, socket will be bound to INADDR_ANY. If the address
  /// is non-zero, socket will be bound to this address only. If the port is
  /// set to zero, the socket will bind at any port (chosen by the OS).
  external pj_sockaddr bound_addr;

  /// Specify the port range for TURN socket binding, relative to the start
  /// port number specified in \a bound_addr. Note that this setting is only
  /// applicable when the start port number is non zero.
  ///
  /// Default value is zero.
  @pj_uint16_t()
  external int port_range;

  /// Specify target value for socket receive buffer size. It will be
  /// applied using setsockopt(). When it fails to set the specified size,
  /// it will try with lower value until the highest possible has been
  /// successfully set.
  ///
  /// Default: 0 (OS default)
  @ffi.UnsignedInt()
  external int so_rcvbuf_size;

  /// Specify target value for socket send buffer size. It will be
  /// applied using setsockopt(). When it fails to set the specified size,
  /// it will try with lower value until the highest possible has been
  /// successfully set.
  ///
  /// Default: 0 (OS default)
  @ffi.UnsignedInt()
  external int so_sndbuf_size;

  /// This specifies TLS settings for TLS transport. It's only applicable when
  /// TLS is used to connect to the TURN server.
  external pj_turn_sock_tls_cfg tls_cfg;
}

/// TLS transport settings.
final class pj_turn_sock_tls_cfg extends ffi.Struct {
  /// Certificate of Authority (CA) list file.
  external pj_str_t ca_list_file;

  /// Certificate of Authority (CA) list directory path.
  external pj_str_t ca_list_path;

  /// Public endpoint certificate file, which will be used as client-
  /// side  certificate for outgoing TLS connection.
  external pj_str_t cert_file;

  /// Optional private key of the endpoint certificate to be used.
  external pj_str_t privkey_file;

  /// Certificate of Authority (CA) buffer. If ca_list_file, ca_list_path,
  /// cert_file or privkey_file are set, this setting will be ignored.
  external pj_ssl_cert_buffer ca_buf;

  /// Public endpoint certificate buffer, which will be used as client-
  /// side  certificate for outgoing TLS connection, and server-side
  /// certificate for incoming TLS connection. If ca_list_file, ca_list_path,
  /// cert_file or privkey_file are set, this setting will be ignored.
  external pj_ssl_cert_buffer cert_buf;

  /// Optional private key buffer of the endpoint certificate to be used.
  /// If ca_list_file, ca_list_path, cert_file or privkey_file are set,
  /// this setting will be ignored.
  external pj_ssl_cert_buffer privkey_buf;

  /// Lookup certificate from OS certificate store with specified criteria.
  ///
  /// Currently only used by TLS backend Windows Schannel, please check
  /// pj_ssl_cert_load_from_store() for more info.
  external pj_ssl_cert_lookup_criteria cert_lookup;

  /// TLS credentials using backend specific objects.
  ///
  /// Currently only used by TLS backend OpenSSL, please check
  /// pj_ssl_cert_load_direct() for more info.
  external pj_ssl_cert_direct cert_direct;

  /// Password to open private key.
  external pj_str_t password;

  /// The ssl socket parameter.
  /// These fields are used by TURN TLS:
  /// - proto
  /// - ciphers_num
  /// - ciphers
  /// - curves_num
  /// - curves
  /// - sigalgs
  /// - entropy_type
  /// - entropy_path
  /// - timeout
  /// - sockopt_params
  /// - sockopt_ignore_error
  /// - enable_renegotiation
  external pj_ssl_sock_param ssock_param;
}

/// TURN session state
enum pj_turn_state_t {
  /// TURN session has just been created.
  PJ_TURN_STATE_NULL(0),

  /// TURN server has been configured and now is being resolved via
  /// DNS SRV resolution.
  PJ_TURN_STATE_RESOLVING(1),

  /// TURN server has been resolved. If there is pending allocation to
  /// be done, it will be invoked immediately.
  PJ_TURN_STATE_RESOLVED(2),

  /// TURN session has issued ALLOCATE request and is waiting for response
  /// from the TURN server.
  PJ_TURN_STATE_ALLOCATING(3),

  /// TURN session has successfully allocated relay resoruce and now is
  /// ready to be used.
  PJ_TURN_STATE_READY(4),

  /// TURN session has issued deallocate request and is waiting for a
  /// response from the TURN server.
  PJ_TURN_STATE_DEALLOCATING(5),

  /// Deallocate response has been received. Normally the session will
  /// proceed to DESTROYING state immediately.
  PJ_TURN_STATE_DEALLOCATED(6),

  /// TURN session is being destroyed.
  PJ_TURN_STATE_DESTROYING(7);

  final int value;
  const pj_turn_state_t(this.value);

  static pj_turn_state_t fromValue(int value) => switch (value) {
    0 => PJ_TURN_STATE_NULL,
    1 => PJ_TURN_STATE_RESOLVING,
    2 => PJ_TURN_STATE_RESOLVED,
    3 => PJ_TURN_STATE_ALLOCATING,
    4 => PJ_TURN_STATE_READY,
    5 => PJ_TURN_STATE_DEALLOCATING,
    6 => PJ_TURN_STATE_DEALLOCATED,
    7 => PJ_TURN_STATE_DESTROYING,
    _ => throw ArgumentError('Unknown value for pj_turn_state_t: $value'),
  };
}

/// TURN transport types, which will be used both to specify the connection
/// type for reaching TURN server and the type of allocation transport to be
/// requested to server (the REQUESTED-TRANSPORT attribute).
enum pj_turn_tp_type {
  /// UDP transport, which value corresponds to IANA protocol number.
  PJ_TURN_TP_UDP(17),

  /// TCP transport, which value corresponds to IANA protocol number.
  PJ_TURN_TP_TCP(6),

  /// TLS transport. The TLS transport will only be used as the connection
  /// type to reach the server and never as the allocation transport type.
  /// The value corresponds to IANA protocol number.
  PJ_TURN_TP_TLS(56);

  final int value;
  const pj_turn_tp_type(this.value);

  static pj_turn_tp_type fromValue(int value) => switch (value) {
    17 => PJ_TURN_TP_UDP,
    6 => PJ_TURN_TP_TCP,
    56 => PJ_TURN_TP_TLS,
    _ => throw ArgumentError('Unknown value for pj_turn_tp_type: $value'),
  };
}

/// Unsigned 16bit integer.
typedef pj_uint16_t = ffi.UnsignedShort;
typedef Dartpj_uint16_t = int;

/// Unsigned 32bit integer.
typedef pj_uint32_t = ffi.UnsignedInt;
typedef Dartpj_uint32_t = int;
typedef pj_uint64_t = ffi.UnsignedLongLong;
typedef Dartpj_uint64_t = int;

/// Unsigned 8bit integer.
typedef pj_uint8_t = ffi.UnsignedChar;
typedef Dartpj_uint8_t = int;
typedef pj_uint_t = pj_uint64_t;

/// This structre describes the parameter to initialize UPnP.
final class pj_upnp_init_param extends ffi.Struct {
  /// The pool factory where memory will be allocated from.
  external ffi.Pointer<pj_pool_factory> factory;

  /// The interface name to use for all UPnP operations.
  ///
  /// If NULL, the library will use the first suitable interface found.
  external ffi.Pointer<ffi.Char> if_name;

  /// The port number to use for all UPnP operations.
  ///
  /// If 0, the library will pick an arbitrary free port.
  @ffi.UnsignedInt()
  external int port;

