    2 => PJMEDIA_SRTP_MANDATORY,
    _ => throw ArgumentError('Unknown value for pjmedia_srtp_use: $value'),
  };

  @override
  String toString() {
    if (this == PJMEDIA_SRTP_DISABLED)
      return "pjmedia_srtp_use.PJMEDIA_SRTP_DISABLED, pjmedia_srtp_use.PJMEDIA_SRTP_UNKNOWN";
    return super.toString();
  }
}

